import{d as v,C as d,o as S,c as V,a3 as l,E as e,j as a,a as t}from"./chunks/framework.D4-ViStF.js";const I=JSON.parse('{"title":"庄子·天运","description":"颜渊问师金、至仁无亲、咸池三奏到应时而变、与化为人，理解庄子论天道与人道。","frontmatter":{"title":"庄子·天运","description":"颜渊问师金、至仁无亲、咸池三奏到应时而变、与化为人，理解庄子论天道与人道。","category":"guide","aliases":["天运","庄子天运","zhuangzi chapter 14"],"source":["《庄子·天运》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-14.md","filePath":"daoism/zhuang-zi/chapter-14.md","lastUpdated":1788516578000}'),N={name:"daoism/zhuang-zi/chapter-14.md"},B=v({...N,setup(A){const o=[{id:"tianyun",sentences:[["天其运乎？地其处乎？日月其争于所乎？孰主张是？孰维纲是？",{text:"孰居无事推而行是",glossary:"juwushi"},"？"],['意者其有机缄而不得已乎？意者其运转而不能自止邪？云者为雨乎？雨者为云乎？孰隆施是？孰居无事淫乐而劝是？风起北方，一西一东，有上仿徨。孰嘘吸是？孰居无事而披拂是？敢问何故？巫咸祒曰："来，吾语女。天有六极五常，帝王顺之则治，逆之则凶。九洛之事，治成德备，临照下土，天下戴之，此谓上皇。"']]}],p=[{id:"juwushi",term:"孰居无事推而行是",pinyin:"shú jū wú shì tuī ér xíng shì",meaning:"谁，无所事事地推动着这一切运行？「居无事」——《天运》的第一个关键词：推动天地运行的，是「居无事」的——不是有意为之，而是自然地推动。"}],h=[{id:"zhiren",sentences:[['商大宰荡问仁于庄子。庄子曰："虎狼，仁也。"曰："何谓也？"庄子曰："父子相亲，何为不仁！"曰："请问至仁。"庄子曰："',{text:"至仁无亲",glossary:"zhirenwuqin"},'。"'],['大宰曰："荡闻之，无亲则不爱，不爱则不孝。谓至仁不孝，可乎？"'],['庄子曰："不然，夫至仁尚矣，孝固不足以言之。此非过孝之言也，不及孝之言也。夫南行者至于郢，北面而不见冥山，是何也？则去之远也。'],["故曰：以敬孝易，以爱孝难；以爱孝易，而忘亲难；忘亲易，使亲忘我难；使亲忘我易，兼忘天下难；兼忘天下易，",{text:"使天下兼忘我难",glossary:"jianwang"},"。"],["夫德遗尧、舜而不为也，利泽施于万世，天下莫知也，岂直大息而言仁孝乎哉！"],["夫孝悌仁义，忠信贞廉，此皆自勉以役其德者也，不足多也。故曰：至贵，国爵并焉；至富，国财并焉；至愿，名誉并焉。是以道不渝。"]]}],g=[{id:"zhirenwuqin",term:"至仁无亲",pinyin:"zhì rén wú qīn",meaning:"最高的仁，没有（特定的）亲。「无亲」，不是没有爱——而是：没有特定的亲疏——爱，不因亲疏而有差别。与儒家「爱有差等」相反。"},{id:"jianwang",term:"使天下兼忘我难",pinyin:"shǐ tiān xià jiān wàng wǒ nán",meaning:"让天下也同时忘掉我——至仁的最终状态：你，忘了天下；天下，也忘了你——但你的德，已经渗透到天下。"}],m=[{id:"xianchi",sentences:[['北门成问于黄帝曰："帝张咸池之乐于洞庭之野，吾始闻之惧，复闻之怠，卒闻之而惑，荡荡默默，乃不自得。"'],['帝曰："汝殆其然哉！吾奏之以人，徵之以天，行之以礼义，建之以大清。夫至乐者，先应之以人事，顺之以天理，行之以五德，应之以自然。然后调理四时，太和万物。'],["四时迭起，万物循生。一盛一衰，文武伦经。一清一浊，阴阳调和，流光其声。蛰虫始作，吾惊之以雷霆。其卒无尾，其始无首。一死一生，一偾一起，所常无穷，而一不可待。汝故惧也。"],["吾又奏之以阴阳之和，烛之以日月之明。其声能短能长，能柔能刚，变化齐一，不主故常。在谷满谷，在坑满坑。涂郤守神，以物为量。其声挥绰，其名高明。是故鬼神守其幽，日月星辰行其纪。吾止之于有穷，流之于无止。"],["子欲虑之而不能知也，望之而不能见也，逐之而不能及也。傥然立于四虚之道，倚于槁梧而吟：'目知穷乎所欲见，力屈乎所欲逐，吾既不及，已夫！'形充空虚，乃至委蛇。汝委蛇，故怠。"],["吾又奏之以无怠之声，调之以自然之命。故若混逐丛生，林乐而无形，布挥而不曳，幽昏而无声。动于无方，居于窈冥，或谓之死，或谓之生；或谓之实，或谓之荣。行流散徙，不主常声。"],["世疑之，稽于圣人。圣也者，达于情而遂于命也。天机不张而五官皆备。此之谓天乐，无言而心说。"],["故有焱氏为之颂曰：'听之不闻其声，视之不见其形，充满天地，苞裹六极。'汝欲听之而无接焉，而故惑也。"],['乐也者，始于惧，惧故祟；吾又次之以怠，怠故遁；卒之于惑，惑故愚；愚故道，道可载而与之俱也。"']]}],u=[{id:"xianchi2",term:"咸池之乐",pinyin:"xián chí zhī yuè",meaning:"咸池：黄帝时代的乐曲名，传说中最高的音乐。北门成听三次：惧→怠→惑。"},{id:"weiyi",term:"委蛇",pinyin:"wēi yí",meaning:"随顺、顺应。形充空虚，乃至委蛇——当人放弃了追逐，身体随顺空虚而放松。"},{id:"tianji2",term:"天机不张而五官皆备",pinyin:"tiān jī bù zhāng ér wǔ guān jiē bèi",meaning:"天然的机能不刻意展开，而五官自然完备。无为而无不为的感官版本。"}],b=[{id:"chugou",sentences:[['孔子西游于卫，颜渊问师金曰："以夫子之行为奚如？"师金曰："惜乎！而夫子其穷哉！"'],['颜渊曰："何也？"师金曰："夫',{text:"刍狗",glossary:"chugou"},"之未陈也，盛以箧衍，巾以文绣，尸祝齐戒以将之。及其已陈也，行者践其首脊，苏者取而爨之而已。"],["将复取而盛以箧衍，巾以文绣，游居寝卧其下，彼不得梦，必且数眯焉。今而夫子亦取先王已陈刍狗，聚弟子游居寝卧其下。"],["故伐树于宋，削迹于卫，穷于商周，是非其梦邪？围于陈蔡之间，七日不火食，死生相与邻，是非其眯邪？"],['夫水行莫如用舟，而陆行莫如用车。以舟之可行于水也，而求推之于陆，则没世不行寻常。古今非水陆与？周鲁非舟车与？今蕲行周于鲁，是犹推舟于陆也！劳而无功，身必有殃。"']]}],x=[{id:"chugou",term:"刍狗",pinyin:"chú gǒu",meaning:"用草扎成的狗，古代祭祀用品。未陈（祭祀前）：盛以箧衍，巾以文绣，极为珍贵；已陈（祭祀后）：行者践其首脊，苏者取而爨之，一文不值。时机论的核心寓言。"}],y=[{id:"tuizhou",sentences:[["彼未知夫无方之传，应物而不穷者也。且子独不见夫桔槔者乎？引之则俯，舍之则仰。彼，人之所引，非引人者也。故俯仰而不得罪于人。"],["故夫三皇五帝之礼义法度，不矜于同而矜于治。故譬三皇五帝之礼义法度，其犹柤梨橘柚邪！其味相反而皆可于口。故礼义法度者，应时而变者也。"],["今取猨狙而衣以周公之服，彼必龁啮挽裂，尽去而后慊。观古今之异，犹猨狙之异乎周公也。"],["故西施病心而颦其里，其里之丑人见之而美之，归亦捧心而颦其里。其里之富人见之，坚闭门而不出；贫人见之，挈妻子而去之走。彼知颦美而不知颦之所以美。惜乎，而夫子其穷哉！"]]}],c=[{id:"wufang",term:"无方之传",pinyin:"wú fāng zhī chuán",meaning:"没有固定方式的传授，随应万物而不穷尽。桔槔的比喻：引之则俯，舍之则仰——完全随应外物。"},{id:"yingshi",term:"礼义法度者，应时而变者也",pinyin:"lǐ yì fǎ dù zhě，yìng shí ér biàn zhě yě",meaning:"礼义法度，是随时代而变化的。《天运》最重要的政治命题。不矜于同而矜于治——形式可以不同，目的是治。"}],f=[{id:"qiudao",sentences:[['孔子行年五十有一而不闻道，乃南之沛见老聃。老聃曰："子来乎？吾闻子，北方之贤者也！子亦得道乎？"孔子曰："未得也。"'],['老子曰："子恶乎求之哉？"曰："吾求之于',{text:"度数",glossary:"dushu"},'，五年而未得也。"老子曰："子又恶乎求之哉？"曰："吾求之于阴阳，十有二年而未得也。"']]}],k=[{id:"dushu",term:"度数",pinyin:"dù shù",meaning:"礼乐的度数、制度规范。孔子第一条求道路：求之于度数，五年而未得。"}],P=[{id:"qulu",sentences:[['老子曰："然，使道而可献，则人莫不献之于其君；使道而可进，则人莫不进之于其亲；使道而可以告人，则人莫不告其兄弟；使道而可以与人，则人莫不与其子孙。'],["然而不可者，无它也，",{text:"中无主而不止，外无正而不行",glossary:"zhongwuzhu"},"。由中出者，不受于外，圣人不出；由外入者，无主于中，圣人不隐。"],["名，公器也，不可多取。仁义，先王之",{text:"蘧庐",glossary:"qulu"},"也，止可以一宿而不可久处。觏而多责。"],["古之至人，假道于仁，托宿于义，以游逍遥之虚，食于苟简之田，立于不贷之圃。逍遥，无为也；苟简，易养也；不贷，无出也。古者谓是采真之游。"],["以富为是者，不能让禄；以显为是者，不能让名。亲权者，不能与人柄，操之则栗，舍之则悲，而一无所鉴，以窥其所不休者，是天之戮民也。"],['怨、恩、取、与、谏、教、生杀八者，正之器也，唯循大变无所湮者为能用之。故曰：正者，正也。其心以为不然者，天门弗开矣。"']]}],q=[{id:"zhongwuzhu",term:"中无主而不止，外无正而不行",pinyin:"zhōng wú zhǔ ér bù zhǐ，wài wú zhèng ér bù xíng",meaning:"内心无根基，道就无法停驻；外在无正道，道就无法施行。道不可传的根本原因。"},{id:"qulu",term:"蘧庐",pinyin:"qú lú",meaning:"古代驿站旁的临时住所。仁义，是先王的临时住所——止可以一宿而不可久处。借用，不执守。"}],z=[{id:"bokang",sentences:[['孔子见老聃而语仁义。老聃曰："夫',{text:"播糠眯目",glossary:"bokang"},"，则天地四方易位矣；蚊虻囋肤，则通昔不寐矣。夫仁义惨然，乃愤吾心，乱莫大焉。"],["吾子使天下无失其朴，吾子亦放风而动，总德而立矣！又奚杰杰然若负建鼓而求亡子者邪！"],["夫鹄不日浴而白，乌不日黔而黑。黑白之朴，不足以为辩；名誉之观，不足以为广。"],['泉涸，鱼相与处于陆，相呴以湿，相濡以沫，不若相忘于江湖。"']]}],j=[{id:"bokang",term:"播糠眯目",pinyin:"bō kāng mī mù",meaning:"播：撒；糠：谷壳；眯：迷住。撒谷壳迷住眼睛——天地四方都会错位。比喻仁义带来的混乱：极小的干扰，造成极大的影响。"}],w=[{id:"jianlong",sentences:[['孔子见老聃归，三日不谈。弟子问曰："夫子见老聃，亦将何规哉？"'],['孔子曰："吾乃今于是乎见龙。龙，合而成体，散而成章，乘乎云气而养乎阴阳。予口张而不能嗋。予又何规老聃哉？"'],['子贡曰："然则人固有尸居而龙见，雷声而渊默，发动如天地者乎？赐亦可得而观乎？"遂以孔子声见老聃。老聃方将倨堂而应，微曰："予年运而往矣，子将何以戒我乎？"'],['子贡曰："夫三皇五帝之治天下不同，其系声名一也。而先生独以为非圣人，如何哉？"老聃曰："小子少进！子何以谓不同？"对曰："尧授舜，舜授禹。禹用力而汤用兵，文王顺纣而不敢逆，武王逆纣而不肯顺，故曰不同。"'],['老聃曰："小子少进，余语汝三皇五帝之治天下：黄帝之治天下，',{text:"使民心一",glossary:"shixin"},"。民有其亲死不哭而民不非也。尧之治天下，",{text:"使民心亲",glossary:"shixin"},"。民有为其亲杀其杀而民不非也。舜之治天下，",{text:"使民心竞",glossary:"shixin"},"。民孕妇十月生子，子生五月而能言，不至乎孩而始谁，则人始有夭矣。禹之治天下，",{text:"使民心变",glossary:"shixin"},"，人有心而兵有顺，杀盗非杀人。自为种而'天下'耳。是以天下大骇，儒墨皆起。其作始有伦，而今乎妇女，何言哉！"],['余语汝：三皇五帝之治天下，名曰治之，而乱莫甚焉。三皇之知，上悖日月之明，下睽山川之精，中堕四时之施。其知惨于蛎虿之尾，鲜规之兽，莫得安其性命之情者，而犹自以为圣人，不可耻乎？其无耻也！"子贡蹴蹴然立不安。']]}],T=[{id:"jianlong2",term:"见龙",pinyin:"jiàn lóng",meaning:"孔子对老聃的最高评价：龙，合而成体，散而成章，乘乎云气而养乎阴阳。予口张而不能嗋——张口却说不出话。"},{id:"shixin",term:"使民心一·亲·竞·变",pinyin:"shǐ mín xīn yī·qīn·jìng·biàn",meaning:"四代民心退化：黄帝心一→尧心亲→舜心竞→禹心变。名曰治之，而乱莫甚焉。"}],G=[{id:"liujing",sentences:[['孔子谓老聃曰："丘治《诗》、《书》、《礼》、《乐》、《易》、《春秋》六经，自以为久矣，孰知其故矣，以奸者七十二君，论先王之道而明周、召之迹，一君无所钩用。甚矣！夫人之难说也？道之难明邪？"'],['老子曰："幸矣，子之不遇治世之君！夫六经，先王之',{text:"陈迹",glossary:"chenji"},"也，岂其所以迹哉！今子之所言，犹迹也。夫迹，履之所出，而迹岂履哉！"],['夫白鶂之相视，眸子不运而风化；虫，雄鸣于上风，雌应于下风而风化。类自为雌雄，故风化。性不可易，命不可变，时不可止，道不可壅。苟得于道，无自而不可；失焉者，无自而可。"'],['孔子不出三月，复见，曰："丘得之矣。乌鹊孺，鱼傅沫，细要者化，有弟而兄啼。久矣，夫丘不与化为人！不与化为人，安能化人。"'],['老子曰："可，丘得之矣！"']]}],C=[{id:"chenji",term:"陈迹",pinyin:"chén jì",meaning:"先王的足迹。六经，是先王的陈迹——岂其所以迹哉！迹，履之所出，而迹岂履哉——足迹，是脚走出来的，但足迹，不是脚。"},{id:"yuhua",term:"与化为人",pinyin:"yǔ huà wéi rén",meaning:"与自然变化，融为一体。久矣，夫丘不与化为人！不与化为人，安能化人——融入变化，方能感化别人。孔子得道的核心。"}];return(R,n)=>{const D=d("DaoReadingPrelude"),i=d("DaoTextReading"),s=d("DaoKeywordCards"),r=d("DaoLineGuide");return S(),V("div",null,[n[0]||(n[0]=l("",3)),e(D,{title:"从天其运乎到与化为人，论天道运行与人道应时",summary:"《天运》以「天其运乎？孰居无事推而行是？」的宇宙论追问开篇，经至仁无亲（七层忘的递进）、咸池三奏（惧·怠·惑·愚·道的聆听路径）、刍狗与推舟于陆（应时而变的时机论），到道不可献、孔子见龙、六经陈迹，最终以孔子「与化为人，方能化人」的得道收束。",points:[{label:"先看",text:"顺着天其运乎→至仁无亲→咸池三奏→刍狗→推舟于陆→求道未得→道不可献→相濡以沫→见龙→六经陈迹这条线走一遍。"},{label:"再问",text:"「礼义法度者，应时而变者也」——什么是不变的？"},{label:"最后",text:"「与化为人，方能化人」——你想影响别人时，先成为变化本身了吗？"}],hint:"这是外篇第七篇。读的时候可以不断回看《天道》——两篇是同一套「虚静无为」主轴的两个展开。"}),n[1]||(n[1]=a("h2",{id:"一、天其运乎·巫咸答",tabindex:"-1"},[t("一、天其运乎·巫咸答 "),a("a",{class:"header-anchor",href:"#一、天其运乎·巫咸答","aria-label":'Permalink to "一、天其运乎·巫咸答"'},"​")],-1)),n[2]||(n[2]=a("h3",{id:"原文",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:o,glossary:p,"default-mode":"classic","aria-label":"天运·天其运乎 原文"}),n[3]||(n[3]=a("h3",{id:"生僻字词",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"天其运乎",pinyin:["tiān","qí","yùn","hū"],meaning:"天，是在运行吗？（天，有没有主动在运行？）"},{term:"地其处乎",pinyin:["dì","qí","chǔ","hū"],meaning:"地，是在静止吗？"},{term:"孰主张是",pinyin:["shú","zhǔ","zhāng"],meaning:"孰：谁；主张：主持、安排。谁在主持这一切？"},{term:"孰维纲是",pinyin:["wéi","gāng"],meaning:"维纲：维系、纲领（维持秩序）。谁在维系这一切的秩序？"},{term:"孰隆施是",pinyin:["lóng","shī"],meaning:"隆施：降下、施予（使雨降落）。谁让雨降落下来？"},{term:"有上仿徨",pinyin:["páng","huáng"],meaning:"仿徨：通「彷徨」，徘徊不定。在上方徘徊。"},{term:"孰嘘吸是",pinyin:["xū","xī"],meaning:"嘘吸：呼气吸气（像呼吸一样驱动风）。谁在呼吸，驱动着风？"},{term:"巫咸祒",pinyin:["wū","xián","sháo"],meaning:"庄子虚构的人物，巫咸：古代神巫；祒：人名。"},{term:"九洛之事",pinyin:["jiǔ","luò"],meaning:"九洛：九畴洛书（古代天地秩序的象征）。"}]}),n[4]||(n[4]=a("h3",{id:"核心句引读",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"孰居无事推而行是——居无事，是天道的运行方式",subtitle:"没有谁在主持，没有谁在维系，没有谁在推动——天，自然运行。",lines:[{text:"天其运乎？地其处乎？日月其争于所乎？孰主张是？孰维纲是？孰居无事推而行是？",tone:"追问",guide:"《天运》以一连串的问开篇——天，是在运行吗？地，是在静止吗？日月，是在争夺位置吗？谁，在主持这一切？谁，在维系这一切的秩序？谁，无所事事地推动着这一切运行？这些问，不是要得到答案——而是通过问，揭示一个事实：没有人——没有谁在主持，没有谁在维系，没有谁在推动——天，自然运行；地，自然静处；日月，自然运转——这一切，都是自然的——不需要主宰，不需要安排。「孰居无事推而行是」——谁，无所事事地推动着这一切——「居无事」——这，是《天运》的第一个关键词：推动天地运行的，是「居无事」的——不是有意为之，不是刻意安排——而是：无所事事地，自然推动——这，就是道的运行方式。"},{text:"云者为雨乎？雨者为云乎？孰隆施是？孰居无事淫乐而劝是？风起北方，一西一东，有上仿徨。孰嘘吸是？孰居无事而披拂是？",tone:"三组问",guide:"云，变成了雨？还是雨，变成了云？——这个问，极为精妙：云与雨，是同一个东西的两种状态——没有谁「变成」谁——它们，在自然地转化。「孰居无事淫乐而劝是」——谁，无所事事，自得其乐地促成了这一切？「淫乐」——不是放纵的乐，而是：沉浸于乐，自得其乐——道，在促成云雨转化的时候，是「自得其乐」的——不是劳苦的，不是有意为之的。三组问（天地·云雨·风），构成一个完整的宇宙图景：天地——运行与静处；云雨——转化与降施；风——起伏与吹拂——三组，都以「孰居无事」作为核心——天地·云雨·风，都是「居无事」的道在运行——这，是《天运》对「天道自然」最完整的描述。"},{text:"巫咸祒曰：天有六极五常，帝王顺之则治，逆之则凶。九洛之事，治成德备，临照下土，天下戴之，此谓上皇。",tone:"政治转",guide:"巫咸，给出了一个回答——天有六极五常（天，有其秩序——六合·五行），帝王顺之则治，逆之则凶（帝王，顺应这个秩序，则天下治；违逆，则凶）。这个回答，是政治层面的——巫咸，把天道的问，转化为政治的答：天道，是帝王治理的依据。但这个回答，与前面的问，有一个落差：前面的问，是：谁在主张？谁在居无事？——答案，应该是：没有谁——道，自然运行——但巫咸，给出的是：帝王，应该顺应天道。这个落差，是有意的：庄子，通过巫咸的回答，引出下一段的主题：天道，自然运行，居无事——但人道（帝王），如何与天道相合？这，是《天运》的核心问题。"}]}),n[5]||(n[5]=a("h2",{id:"二、商大宰荡问仁·至仁无亲",tabindex:"-1"},[t("二、商大宰荡问仁·至仁无亲 "),a("a",{class:"header-anchor",href:"#二、商大宰荡问仁·至仁无亲","aria-label":'Permalink to "二、商大宰荡问仁·至仁无亲"'},"​")],-1)),n[6]||(n[6]=a("h3",{id:"原文-1",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:h,glossary:g,"default-mode":"classic","aria-label":"天运·至仁无亲 原文"}),n[7]||(n[7]=a("h3",{id:"生僻字词-1",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"商大宰荡",pinyin:["shāng","dà","zǎi","dàng"],meaning:"商：宋国（商朝后裔）；大宰：官职（相当于宰相）；荡：人名。"},{term:"至仁无亲",pinyin:["zhì","rén","wú","qīn"],meaning:"最高的仁，没有（特定的）亲。"},{term:"夫至仁尚矣",pinyin:["shàng"],meaning:"尚：高远、超越。至仁，是高远的，孝本来就不足以描述它。"},{term:"是以道不渝",pinyin:["yú"],meaning:"渝：改变。所以，道，不会改变。"}]}),n[8]||(n[8]=a("h3",{id:"核心句引读-1",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"至仁无亲——超越亲疏的爱",subtitle:"「无亲」，不是没有爱——而是：没有特定的亲疏——爱，不因亲疏而有差别。",lines:[{text:"商大宰荡问仁于庄子。庄子曰：虎狼，仁也。……庄子曰：至仁无亲。",tone:"三回合",guide:"三个回合，层层递进：第一回合——虎狼，仁也——大宰荡问仁，庄子说：虎狼，也是仁的——这，是一个挑衅：儒家的仁，是人独有的——庄子，把仁，给了虎狼；第二回合——父子相亲，何为不仁——庄子解释：虎狼，父子相亲——父子相亲，是仁的基本形式——仁，不是人类独有的——仁，是一切生命的本然——父子相亲，是自然的——不需要被教导，不需要被标榜；第三回合——至仁无亲——大宰荡追问至仁，庄子说：至仁，无亲——「无亲」，不是没有爱——而是：没有特定的亲疏——普通的仁，是爱自己的父母，爱自己的家人——这，是有亲的仁——至仁，是：没有特定的亲疏——爱，不因亲疏而有差别——这，与儒家的「爱有差等」完全相反。"},{text:"夫南行者至于郢，北面而不见冥山，是何也？则去之远也。",tone:"南行至郢",guide:"大宰荡提出反驳：无亲，则不爱；不爱，则不孝——至仁不孝，可以吗？庄子回答：夫至仁尚矣，孝固不足以言之——至仁，是高远的——孝，本来就不足以描述它——此非过孝之言也，不及孝之言也——这，不是超过孝的说法——而是，还没有到达孝的说法——至仁，在孝之上——孝，无法衡量至仁。比喻：南行至郢——向南走到了楚国的郢都——向北看，已经看不见北方的冥山了——为什么？——因为离得太远了——至仁，是郢；孝，是冥山——当你到达了至仁（郢）——孝（冥山），已经在你身后很远的地方——不是孝消失了，而是：你，已经走得太远，孝，无法衡量你了。"},{text:"以敬孝易，以爱孝难；以爱孝易，而忘亲难；忘亲易，使亲忘我难；使亲忘我易，兼忘天下难；兼忘天下易，使天下兼忘我难。",tone:"七层",guide:"七层递进——每一层，都比上一层更难：以敬孝（容易——表面的恭敬）→以爱孝（难——真实的爱）→忘亲（难——超越亲疏）→使亲忘我（难——让亲人也超越对我的执着）→兼忘天下（难——超越一切人我关系）→使天下兼忘我（难——让天下也忘掉我）。这七层，是「仁」的层级跃迁——最高的「使天下兼忘我」——这，与下一句完全呼应：夫德遗尧、舜而不为也，利泽施于万世，天下莫知也——你的德，超越了尧舜——你的恩泽，施予了万世——但天下，没有人知道——因为：你，不留痕迹——你，「居无事」地施予——就像天道，居无事地运行——没有人知道是谁在推动。"},{text:"夫孝悌仁义，忠信贞廉，此皆自勉以役其德者也，不足多也。故曰：至贵，国爵并焉；至富，国财并焉；至愿，名誉并焉。是以道不渝。",tone:"役德",guide:"孝悌仁义，忠信贞廉——这八个，都是儒家推崇的德目——此皆自勉以役其德者也——这些，都是自我勉励来役使德的——「役其德」——把德，当成工具——当成自我提升的工具，当成社会认可的工具——这，不是真正的德——真正的德，是本然的，不需要自我勉励——一旦需要自我勉励，说明德，已经不是本然的了——不足多也——不值得推崇。三个「至」——至贵，国爵并焉（真正的贵，不是爵位）；至富，国财并焉（真正的富，不是财富）；至愿，名誉并焉（真正的愿望，不是名誉）——三个「至」，指向同一个东西：道——是以道不渝——道，不会改变——道，是至贵·至富·至愿——国爵·国财·名誉，在道面前，都相形见绌。"}]}),n[9]||(n[9]=a("h2",{id:"三、北门成问乐·咸池三奏",tabindex:"-1"},[t("三、北门成问乐·咸池三奏 "),a("a",{class:"header-anchor",href:"#三、北门成问乐·咸池三奏","aria-label":'Permalink to "三、北门成问乐·咸池三奏"'},"​")],-1)),n[10]||(n[10]=a("h3",{id:"原文-2",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:m,glossary:u,"default-mode":"classic","aria-label":"天运·咸池三奏 原文"}),n[11]||(n[11]=a("h3",{id:"生僻字词-2",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"北门成",pinyin:["běi","mén","chéng"],meaning:"庄子虚构的人物，黄帝的臣子。"},{term:"咸池之乐",pinyin:["xián","chí","zhī","yuè"],meaning:"咸池：黄帝时代的乐曲名，传说中最高的音乐。"},{term:"洞庭之野",pinyin:["dòng","tíng","zhī","yě"],meaning:"洞庭：此处非洞庭湖，而是广阔的原野（天地之间的旷野）。"},{term:"苞裹六极",pinyin:["bāo","guǒ","liù","jí"],meaning:"苞裹：包裹、包容；六极：六合（上下四方）。包裹六合（无所不包）。"},{term:"怠故遁",pinyin:["dùn"],meaning:"遁：退隐、消融。怠，使人消融（放松消融）。"},{term:"惑故愚",pinyin:["huò","gù","yú"],meaning:"惑，使人归于愚（愚：素朴、无知无执）。"}]}),n[12]||(n[12]=a("h3",{id:"核心句引读-2",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"始于惧，惧故祟；怠故遁；卒之于惑，惑故愚；愚故道",subtitle:"惧·怠·惑·愚——不是问题，而是：进入道的过程。",lines:[{text:"帝张咸池之乐于洞庭之野，吾始闻之惧，复闻之怠，卒闻之而惑，荡荡默默，乃不自得。",tone:"三听",guide:"北门成，听了三次咸池之乐——三次，三种感受：始闻之——惧（恐惧）；复闻之——怠（懈怠）；卒闻之——惑（迷惑）。最终：荡荡默默，乃不自得（空荡荡，沉默无声，无法自持）。北门成，不理解这三种感受——他，困惑：为什么听一首乐，会经历这三种变化？黄帝，回答：「汝殆其然哉！」——你，大概就应该是这样的感受——这一句，极为重要：黄帝，不是说北门成的感受是错的——而是：这三种感受，是正确的——是咸池之乐，应该带来的感受——惧·怠·惑，不是问题，而是：过程。"},{text:"其卒无尾，其始无首。一死一生，一偾一起，所常无穷，而一不可待。汝故惧也。",tone:"第一奏",guide:"第一奏，是「人·天·礼义·大清」——至乐，先从人事开始，顺之以天理，行之以五德，应之以自然——四步，层层递进，最终到达自然。然后，宇宙的运行展开：四时迭起，万物循生——一盛一衰，文武伦经——一清一浊，阴阳调和——蛰虫始作，吾惊之以雷霆——这些，都在咸池之乐中——咸池之乐，是宇宙运行的音乐化。其卒无尾，其始无首（无始无终），一死一生，一偾一起（循环不息），所常无穷，而一不可待（一刻也不停留）——汝故惧也。为什么这会让人惧？因为：人，习惯于有始有终——习惯于：开始·过程·结束——但咸池之乐，无始无终——习惯于：生命是线性的——但咸池之乐，是循环的——习惯于：可以等待，可以预期——但咸池之乐，一不可待——这种「无始无终·循环不息·一不可待」——打破了人的一切习惯性认知——所以：惧。惧，是人面对天道时最初的反应：天道，太大了，太无始无终了——人，被震慑了。"},{text:"子欲虑之而不能知也，望之而不能见也，逐之而不能及也。……形充空虚，乃至委蛇。汝委蛇，故怠。",tone:"第二奏",guide:"第二奏，是「阴阳之和·日月之明」——其声能短能长，能柔能刚，变化齐一，不主故常——在谷满谷，在坑满坑（道的「随物赋形」：道，不固定于任何形状——在哪里，就充满哪里）。吾止之于有穷，流之于无止（有穷，是有限的；无止，是无限的——咸池之乐，同时存在于有限与无限之间——这，是道的本质：有形与无形并存）。三个「不能」——虑之，不能知（用思维，无法认知）；望之，不能见（用眼睛，无法看见）；逐之，不能及（用行动，无法追及）——思维·眼睛·行动——人的三种认知方式，全部失效。于是：傥然立于四虚之道——茫然地立于四方虚空之中——倚于槁梧而吟——「目知穷乎所欲见，力屈乎所欲逐，吾既不及，已夫！」——这，是放弃——但这种放弃，是必要的——因为：人，必须先放弃用感官和思维来追逐道——才能进入下一个阶段。形充空虚，乃至委蛇——汝委蛇，故怠——「委蛇」——随顺、放松——当人放弃了追逐——身体随顺空虚而放松——这种放松，感觉上是「怠」——但实则，是进入了更深的状态——怠，不是真的懈怠——而是：放下了紧张，进入了松弛。"},{text:"乐也者，始于惧，惧故祟；吾又次之以怠，怠故遁；卒之于惑，惑故愚；愚故道，道可载而与之俱也。",tone:"五阶段",guide:"这，是全段最重要的收束——也是《天运》最深刻的一句话——五个阶段，层层递进：惧→祟（精神升起）——恐惧，打破了人的惯性——精神，被震动，升起——这，是进入道的第一步：打破惯性；怠→遁（消融退隐）——懈怠，不是坏事——懈怠，是放下了紧张，放下了追逐——人，消融进入空虚——这，是进入道的第二步：放下追逐；惑→愚（归于素朴）——迷惑，是：一切概念，都失效了——死·生·实·荣，都无法定义天乐——人，陷入迷惑——但迷惑，使人归于「愚」——愚：素朴、无知无执——这，是进入道的第三步：放下概念；愚故道——愚，故得道——这，是《天运》最反直觉的一句话：不是聪明得道，不是博学得道——而是：愚，得道——「愚」，不是真的愚蠢——而是：放下了一切聪明·博学·概念之后的素朴；道可载而与之俱也——道，可以承载，与之同行——当你经历了惧·怠·惑·愚——道，自然来承载你——与你同行。"}]}),n[13]||(n[13]=a("h2",{id:"四、孔子西游·师金论刍狗",tabindex:"-1"},[t("四、孔子西游·师金论刍狗 "),a("a",{class:"header-anchor",href:"#四、孔子西游·师金论刍狗","aria-label":'Permalink to "四、孔子西游·师金论刍狗"'},"​")],-1)),n[14]||(n[14]=a("h3",{id:"原文-3",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:b,glossary:x,"default-mode":"classic","aria-label":"天运·师金论刍狗 原文"}),n[15]||(n[15]=a("h3",{id:"生僻字词-3",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"颜渊问师金",pinyin:["shī","jīn"],meaning:"师金：庄子虚构的人物，一位有见识的人。"},{term:"盛以箧衍",pinyin:["qiè","yǎn"],meaning:"箧衍：精美的竹箱。用精美的竹箱盛放。"},{term:"巾以文绣",pinyin:["jīn","wén","xiù"],meaning:"巾：用布覆盖；文绣：有花纹的绣布。用有花纹的绣布覆盖。"}]}),n[16]||(n[16]=a("h3",{id:"核心句引读-3",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"刍狗——未陈珍贵，已陈废物",subtitle:"任何东西，都有其时机——时机到了，它是珍宝；时机过了，它是废物。",lines:[{text:"夫刍狗之未陈也，盛以箧衍，巾以文绣，尸祝齐戒以将之。及其已陈也，行者践其首脊，苏者取而爨之而已。",tone:"刍狗",guide:"刍狗——用草扎成的狗——古代祭祀用品——祭祀之前，极为珍贵；祭祀之后，一文不值。未陈（祭祀之前）：盛以箧衍（用精美的竹箱盛放），巾以文绣（用绣布覆盖），尸祝齐戒以将之（祭祀者斋戒，恭敬护送）——极度珍贵，极度恭敬。已陈（祭祀之后）：行者践其首脊（过路人踩踏它的头和脊背），苏者取而爨之而已（割草人拿去当柴烧）——一文不值，随意处置。刍狗，本身没有变——变的，是：时机——未陈，是它的时机；已陈，时机已过——时机过了，再珍贵的东西，也变成了废物。这，是《天运》「应时而变」的核心寓言。"},{text:"将复取而盛以箧衍，巾以文绣，游居寝卧其下，彼不得梦，必且数眯焉。",tone:"数眯",guide:"如果，有人把已陈的刍狗，重新取来——重新用箧衍盛放，用绣布覆盖——在它下面游居寝卧——结果：必且数眯焉——必定会频繁做噩梦。为什么？因为：刍狗，已陈——它，已经完成了它的使命——它，已经是废物了——你，把废物当珍宝——你，在废物下面寝卧——这，是违背时机的——违背时机，必有噩梦。这个比喻，极为精准：先王的礼义，是已陈的刍狗——在先王的时代，它是珍宝——但在孔子的时代，它已经是废物了——孔子，把废物当珍宝——在废物下面寝卧——所以：噩梦（困境）不断。"},{text:"今而夫子亦取先王已陈刍狗，聚弟子游居寝卧其下。故伐树于宋，削迹于卫，穷于商周，是非其梦邪？围于陈蔡之间，七日不火食，死生相与邻，是非其眯邪？",tone:"孔子的梦",guide:"师金，把刍狗的比喻，直接对应到孔子——孔子，取先王已陈刍狗——先王的礼义，是已陈的刍狗——孔子和弟子，在废物下面寝卧——结果：伐树于宋（在宋国，被人砍掉讲学的大树——这，是梦）；削迹于卫（在卫国，被驱逐——这，是梦）；穷于商周（在商·周地，陷入困境——这，是梦）；围于陈蔡之间，七日不火食，死生相与邻（被围困在陈蔡之间，七天没有热食，生死之间——这，是噩梦）。师金，用孔子的真实经历，证明了刍狗的比喻：孔子，执守先王已陈的礼义——结果，噩梦连连——不是孔子不好——而是：时机已过——在已陈的刍狗下面寝卧，必有噩梦。"}]}),n[17]||(n[17]=a("h2",{id:"五、推舟于陆·无方之传",tabindex:"-1"},[t("五、推舟于陆·无方之传 "),a("a",{class:"header-anchor",href:"#五、推舟于陆·无方之传","aria-label":'Permalink to "五、推舟于陆·无方之传"'},"​")],-1)),n[18]||(n[18]=a("h3",{id:"原文-4",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:y,glossary:c,"default-mode":"classic","aria-label":"天运·推舟于陆 原文"}),n[19]||(n[19]=a("h3",{id:"生僻字词-4",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"无方之传",pinyin:["wú","fāng","zhī","chuán"],meaning:"没有固定方式的传授（随时应变的传授）。"},{term:"桔槔者",pinyin:["jié","gāo"],meaning:"桔槔：古代汲水工具，一根杠杆，一端挂水桶，一端挂重物，利用杠杆原理汲水。"},{term:"柤梨橘柚",pinyin:["zhā","lí","jú","yòu"],meaning:"柤：山楂；梨；橘；柚。四种水果。"},{term:"猨狙",pinyin:["yuán","jū"],meaning:"猨狙：猿猴。"}]}),n[20]||(n[20]=a("h3",{id:"核心句引读-4",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"礼义法度者，应时而变者也",subtitle:"礼义法度，不需要相同——只需要：治——形式，可以不同；目的，是治。",lines:[{text:"彼未知夫无方之传，应物而不穷者也。且子独不见夫桔槔者乎？引之则俯，舍之则仰。彼，人之所引，非引人者也。故俯仰而不得罪于人。",tone:"桔槔",guide:"无方之传——没有固定方式的传授——应物而不穷（随应万物而不穷尽）。孔子，不知道「无方之传」——他，执守一种固定的方式（先王礼义）——不随时代而变——所以，穷。桔槔的比喻——桔槔，是古代汲水工具：一根杠杆，一端挂水桶，一端挂重物——引之则俯（拉它，它低下），舍之则仰（放开，它抬起）——彼，人之所引，非引人者也（桔槔，是被人拉动的，不是拉动人的）——故俯仰而不得罪于人（所以，随人俯仰，不得罪于人）。桔槔，是「应物而不穷」的象征：它，没有固定的姿态——人拉，它俯；人放，它仰——完全随应外物——所以，永远不会与人相违——这，是「无方之传」的具体形象。"},{text:"故夫三皇五帝之礼义法度，不矜于同而矜于治。故譬三皇五帝之礼义法度，其犹柤梨橘柚邪！其味相反而皆可于口。故礼义法度者，应时而变者也。",tone:"柤梨橘柚",guide:"三皇五帝之礼义法度——三皇五帝，各有不同的礼义法度——不矜于同而矜于治——不强调相同，而强调治理有效——这，是《天运》对礼义法度最重要的定义：礼义法度，不需要相同——只需要：治——有效地治理，才是礼义法度的目的——形式，可以不同；目的，是治。柤梨橘柚的比喻——柤（山楂）·梨·橘·柚——四种水果，味道各不相同：山楂，酸；梨，甜；橘，酸甜；柚，苦甜——其味相反——但皆可于口——都适合于口，都好吃。三皇五帝的礼义法度，就像这四种水果：形式不同，味道不同——但都有效（皆可于口）——都达到了「治」的目的。故礼义法度者，应时而变者也——所以，礼义法度，是随时代而变化的——这，是《天运》最重要的政治命题。"},{text:"以舟之可行于水也，而求推之于陆，则没世不行寻常。古今非水陆与？周鲁非舟车与？今蕲行周于鲁，是犹推舟于陆也！劳而无功，身必有殃。",tone:"推舟于陆",guide:"推舟于陆——这，是《天运》最著名的比喻——水行，用舟；陆行，用车——各有其工具，各有其场合。以舟之可行于水，而求推之于陆——因为船在水上可以行，就想把船推到陆地上——则没世不行寻常——终其一生，也走不了一点点。古今非水陆与？（古代和今天，不就是水和陆吗？）周鲁非舟车与？（周朝的礼义和鲁国，不就是船和陆地吗？）今蕲行周于鲁，是犹推舟于陆也！——现在希望在鲁国推行周朝的礼义——这，就像在陆地上推船——劳而无功，身必有殃。这个比喻，极为精准：水（古代·周朝的时代），陆（今天·鲁国的时代），舟（周朝的礼义·适合古代的工具），车（今天需要的礼义·适合今天的工具）——孔子，把舟（周礼）推到陆（鲁国）——劳而无功——不是孔子不努力——不是周礼不好——而是：工具，用错了场合。"},{text:"今取猨狙而衣以周公之服，彼必龁啮挽裂，尽去而后慊。……故西施病心而颦其里……彼知颦美而不知颦之所以美。惜乎，而夫子其穷哉！",tone:"猨狙·西施",guide:"猨狙（猿猴），穿上周公的礼服——彼必龁啮挽裂，尽去而后慊——它，必定用牙咬，用手撕，把衣服全部去掉，才满足。观古今之异，犹猨狙之异乎周公也——今天的人，不是古代的人——强迫今天的人，穿古代的礼服（周礼）——结果，必定是：撕掉。西施颦的比喻——西施，心口疼痛，皱眉走在乡里——乡里的丑女，看见西施皱眉，觉得很美——回去，也捂着心口皱眉——结果：富人紧闭门不出，贫人带着妻儿逃走——彼知颦美而不知颦之所以美——她，知道皱眉是美的——却不知道皱眉之所以美的原因——西施皱眉之所以美，不是因为皱眉本身——而是因为：西施——天生丽质。孔子，也是如此：孔子，知道先王礼义是好的——但不知道先王礼义之所以好的原因——先王礼义之所以好，是因为：它，应时而生——它，是那个时代的「西施」——但在今天，强行模仿，是丑的。「惜乎，而夫子其穷哉！」——师金，用这句话，首尾呼应。"}]}),n[21]||(n[21]=a("h2",{id:"六、孔子行年·求道未得",tabindex:"-1"},[t("六、孔子行年·求道未得 "),a("a",{class:"header-anchor",href:"#六、孔子行年·求道未得","aria-label":'Permalink to "六、孔子行年·求道未得"'},"​")],-1)),n[22]||(n[22]=a("h3",{id:"原文-5",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:f,glossary:k,"default-mode":"classic","aria-label":"天运·孔子行年 原文"}),n[23]||(n[23]=a("h3",{id:"生僻字词-5",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"南之沛",pinyin:["pèi"],meaning:"沛：地名，老聃隐居之处。"},{term:"度数",pinyin:["dù","shù"],meaning:"礼乐的度数、制度规范。"},{term:"阴阳",pinyin:["yīn","yáng"],meaning:"阴阳之道、天地变化之理。"}]}),n[24]||(n[24]=a("h3",{id:"核心句引读-5",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"孔子行年五十有一而不闻道——未得也",subtitle:"两条路，都是「向外求」——度数，是外在的制度；阴阳，是外在的规律——所以，十七年，未得。",lines:[{text:"孔子行年五十有一而不闻道，乃南之沛见老聃。",tone:"五十一",guide:"五十一岁，未闻道——这一句，极为沉重：孔子，五十一岁——他，已经研究了礼乐·度数·阴阳——五年，求之于度数，未得——十二年，求之于阴阳，未得——十七年，两条路，都走到了尽头。「乃南之沛见老聃」——于是，向南，去沛，见老聃——这个「乃」，是转折——是孔子，走投无路之后的转向——不是主动求教，而是：走投无路——这，是孔子此行的真实背景。"},{text:"老聃曰：子来乎？吾闻子，北方之贤者也！子亦得道乎？孔子曰：未得也。",tone:"未得",guide:"老聃，一见孔子，先问：子亦得道乎？——这个问，不是寒暄——而是：直接切入核心——老聃，知道孔子来的目的——他，不绕弯子。孔子，「未得也」——两个字，极为诚实——五十一岁，研究了十七年——「未得」——这种坦承，是孔子此行最重要的姿态：他，放下了「北方之贤者」的身份——承认：未得。"},{text:"吾求之于度数，五年而未得也。……吾求之于阴阳，十有二年而未得也。",tone:"向外求",guide:"老聃，两问——孔子，两答。第一条路：度数（礼乐的制度规范）——五年，未得；第二条路：阴阳（天地变化之理）——十二年，未得。两条路，都是「向外求」——度数，是外在的制度——阴阳，是外在的规律——孔子，在外在的东西中，寻找道——所以，十七年，未得。这，与《天道》「轮扁斫轮」完全呼应：道，不在书中，不在度数中，不在阴阳中——道，在「不徐不疾·得之于手而应于心」中——在内，不在外。"}]}),n[25]||(n[25]=a("h2",{id:"七、道不可献·名是公器·仁义蘧庐",tabindex:"-1"},[t("七、道不可献·名是公器·仁义蘧庐 "),a("a",{class:"header-anchor",href:"#七、道不可献·名是公器·仁义蘧庐","aria-label":'Permalink to "七、道不可献·名是公器·仁义蘧庐"'},"​")],-1)),n[26]||(n[26]=a("h3",{id:"原文-6",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-6","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:P,glossary:q,"default-mode":"classic","aria-label":"天运·道不可献 原文"}),n[27]||(n[27]=a("h3",{id:"生僻字词-6",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"觏而多责",pinyin:["gòu"],meaning:"觏：见面、遇到。见了面，反而多受责备。"},{term:"采真之游",pinyin:["cǎi","zhēn","zhī","yóu"],meaning:"采摘本真之游。至人的生活方式：逍遥无为·苟简易养·不贷无出。"}]}),n[28]||(n[28]=a("h3",{id:"核心句引读-6",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"中无主而不止，外无正而不行——道不可传的根本原因",subtitle:"名，公器也，不可多取；仁义，先王之蘧庐也，止可以一宿而不可久处。",lines:[{text:"使道而可献，则人莫不献之于其君……然而不可者，无它也，中无主而不止，外无正而不行。",tone:"道不可献",guide:"四个「使道而可」——如果道可以奉献（可献），那么没有人不把它献给君主；如果道可以进献（可进），那么没有人不进献给他的亲人；如果道可以告诉人（可告），那么没有人不告诉他的兄弟；如果道可以给予人（可与），那么没有人不给予他的子孙。然而不可者，无它也——然而做不到，没有别的原因——中无主而不止（内心无根基，道就无法停驻），外无正而不行（外在无正道，道就无法施行）。由中出者，不受于外，圣人不出（从内心发出的，如果外在不接受，圣人就不发出）；由外入者，无主于中，圣人不隐（从外进入的，如果内心无根基，圣人就不接受）。道，不是可以被给予的东西——给予道，需要接受者「中有所主」——内心无根基的人，即使道来到面前，也无法接受。"},{text:"名，公器也，不可多取。仁义，先王之蘧庐也，止可以一宿而不可久处。觏而多责。",tone:"公器·蘧庐",guide:"名，公器也，不可多取——名，属于所有人（公共的器），不可以多占取——名，是公共的，不是私有的——多取，是侵占公共的东西。仁义，先王之蘧庐也——仁义，是先王的临时住所（蘧庐：古代驿站旁的临时住所）——止可以一宿而不可久处（只可以住一夜，不可以长久居住）——仁义，是临时的，不是家——借用一下，可以；长期居住，不行。觏而多责（见了面，反而多受责备）。古之至人，假道于仁，托宿于义（至人对待仁义的方式：借用仁，借宿义——借用，不执守），以游逍遥之虚（在逍遥的虚境中游），食于苟简之田（在苟简的田中食），立于不贷之圃（在不贷的圃中立）——逍遥，无为也；苟简，易养也；不贷，无出也——古者谓是采真之游（这叫做采摘本真之游）。"},{text:"亲权者，不能与人柄，操之则栗，舍之则悲，而一无所鉴，以窥其所不休者，是天之戮民也。……其心以为不然者，天门弗开矣。",tone:"戮民·天门",guide:"以富为是者，不能让禄（把富当作对的人，不能推让俸禄）；以显为是者，不能让名；亲权者，不能与人柄（亲近权力的人，不能把权柄交给人）——操之则栗（握着它，就战栗），舍之则悲（放下它，就悲伤）——而一无所鉴（一点也不鉴戒），以窥其所不休者（还盯着那个不停追求的东西）——是天之戮民也（这是受天刑罚的人——自我惩罚的人）。怨、恩、取、与、谏、教、生杀八者，正之器也（八种匡正的工具）——唯循大变无所湮者为能用之（只有顺应大变化而不停滞的人，才能使用它们）——故曰：正者，正也——其心以为不然者，天门弗开矣（心里不认同的人，天门不会打开——道无法进入）。"}]}),n[29]||(n[29]=a("h2",{id:"八、孔子见老聃·播糠眯目·相濡以沫",tabindex:"-1"},[t("八、孔子见老聃·播糠眯目·相濡以沫 "),a("a",{class:"header-anchor",href:"#八、孔子见老聃·播糠眯目·相濡以沫","aria-label":'Permalink to "八、孔子见老聃·播糠眯目·相濡以沫"'},"​")],-1)),n[30]||(n[30]=a("h3",{id:"原文-7",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-7","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:z,glossary:j,"default-mode":"classic","aria-label":"天运·播糠眯目 原文"}),n[31]||(n[31]=a("h3",{id:"生僻字词-7",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"播糠眯目",pinyin:["bō","kāng","mī","mù"],meaning:"播：撒；糠：谷壳；眯：迷住。撒谷壳迷住眼睛——天地四方都会错位。"},{term:"放风而动",pinyin:["fàng","fēng","ér","dòng"],meaning:"顺应自然而动。吾子亦放风而动，总德而立：顺应自然而动，以德为本而立。"},{term:"总德而立",pinyin:["zǒng","dé","ér","lì"],meaning:"以德为本而立。与《天道》「放德而行」呼应。"}]}),n[32]||(n[32]=a("h3",{id:"核心句引读-7",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"播糠眯目，则天地四方易位矣——仁义，乱莫大焉",subtitle:"极小的干扰，造成极大的影响——仁义，是最大的乱。",lines:[{text:"夫播糠眯目，则天地四方易位矣；蚊虻囋肤，则通昔不寐矣。夫仁义惨然，乃愤吾心，乱莫大焉。",tone:"眯目",guide:"孔子见老聃而语仁义。老聃说：夫播糠眯目（撒谷壳迷住眼睛），则天地四方易位矣（天地四方都会错位）——蚊虻囋肤（蚊虻叮咬皮肤），则通昔不寐矣（整夜睡不着）——夫仁义惨然，乃愤吾心，乱莫大焉（仁义残酷，搅乱我的心，没有比这更乱的）。「播糠眯目」——极小的干扰，造成极大的影响——一粒糠，进入眼睛——天地四方，全部错位——仁义，就是那粒糠——它，是极小的「人为」——但它，进入人心——人心的天地四方，全部错位——所以：仁义，乱莫大焉。"},{text:"吾子使天下无失其朴，吾子亦放风而动，总德而立矣！又奚杰杰然若负建鼓而求亡子者邪！",tone:"放风而动",guide:"正面答案——吾子使天下无失其朴（你使天下不失其本真），吾子亦放风而动（你顺应自然而动），总德而立矣（以德为本而立）！又奚杰杰然若负建鼓而求亡子者邪（又何必急切用力，像背着大鼓去找逃跑的孩子一样）！「放风而动，总德而立」——与《天道》「放德而行，遁遁而趋」呼应——顺应自然而动，以德为本而立——不是去推行仁义——而是：本然地动，本然地立——天下，自然不失其朴。"},{text:"夫鹄不日浴而白，乌不日黔而黑。黑白之朴，不足以为辩；名誉之观，不足以为广。泉涸，鱼相与处于陆，相呴以湿，相濡以沫，不若相忘于江湖。",tone:"相忘江湖",guide:"夫鹄不日浴而白（天鹅不需要每天洗澡，自然是白的），乌不日黔而黑（乌鸦不需要每天染黑，自然是黑的）——黑白之朴，不足以为辩（黑白本来的样子，不值得去分辨——本然，不需要论证）——名誉之观，不足以为广（名誉的观感，不值得去追求）。泉涸，鱼相与处于陆（泉水干涸，鱼儿困在陆地上），相呴以湿（互相用湿气滋润），相濡以沫（用唾沫润湿）——不若相忘于江湖（不如在江湖中相忘）。仁义，是相濡以沫——是困境中的补救——是泉涸之后的互相湿润；道，是相忘于江湖——是本然的自由——是在江湖中的各自自在。这，是《庄子》全书最著名的句子之一。"}]}),n[33]||(n[33]=a("h2",{id:"九、孔子见龙·子贡见老聃",tabindex:"-1"},[t("九、孔子见龙·子贡见老聃 "),a("a",{class:"header-anchor",href:"#九、孔子见龙·子贡见老聃","aria-label":'Permalink to "九、孔子见龙·子贡见老聃"'},"​")],-1)),n[34]||(n[34]=a("h3",{id:"原文-8",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-8","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:w,glossary:T,"default-mode":"classic","aria-label":"天运·孔子见龙 原文"}),n[35]||(n[35]=a("h3",{id:"生僻字词-8",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"亦将何规哉",pinyin:["yì","jiāng","hé","guī","zāi"],meaning:"规：规劝、教导。将会规劝他什么呢？"},{term:"见龙",pinyin:["jiàn","lóng"],meaning:"孔子对老聃的最高评价：龙，合而成体，散而成章。予口张而不能嗋——张口却说不出话。"},{term:"尸居龙见",pinyin:["shī","jū","lóng","xiàn"],meaning:"尸居：像尸体一样安静居处；龙见：像龙一样显现。静如尸，动如龙。"},{term:"渊默雷声",pinyin:["yuān","mò","léi","shēng"],meaning:"渊默：深渊般的沉默；雷声：雷鸣般的声音。默如渊，声如雷。"}]}),n[36]||(n[36]=a("h3",{id:"核心句引读-8",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"见龙——合而成体，散而成章，乘乎云气而养乎阴阳",subtitle:"孔子对老聃的最高评价：予口张而不能嗋——张口却说不出话。",lines:[{text:"吾乃今于是乎见龙。龙，合而成体，散而成章，乘乎云气而养乎阴阳。予口张而不能嗋。予又何规老聃哉？",tone:"见龙",guide:"孔子见老聃归，三日不谈——弟子问：夫子见老聃，亦将何规哉（将会规劝他什么呢）？孔子曰：吾乃今于是乎见龙（我今天在这里见到了龙）——龙，合而成体（聚合起来成为形体），散而成章（散开去成为花纹）——乘乎云气而养乎阴阳（乘着云气，养育阴阳）——予口张而不能嗋（我张开嘴，却合不拢——张口结舌）——予又何规老聃哉（我又能规劝老聃什么呢）！「见龙」——是孔子对老聃的最高评价：龙，变化无方，不可名状——老聃，就是那条龙——孔子，无法规劝他——因为：他，已经超越了一切可规劝的层面。"},{text:"余语汝三皇五帝之治天下：黄帝之治天下，使民心一。尧之治天下，使民心亲。舜之治天下，使民心竞。禹之治天下，使民心变。……名曰治之，而乱莫甚焉。",tone:"四代退化",guide:"子贡见老聃——三皇五帝之治天下不同，其系声名一也——而先生独以为非圣人，如何哉？老聃说：四代民心退化——黄帝之治天下，使民心一（纯一）；尧之治天下，使民心亲（相亲）；舜之治天下，使民心竞（相争）；禹之治天下，使民心变（变诈）——从「一」到「亲」到「竞」到「变」——民心，一代不如一代——名曰治之，而乱莫甚焉（名义上叫治理，而混乱没有比这更严重的）。三皇之知，上悖日月之明，下睽山川之精，中堕四时之施——其知惨于蛎虿之尾（比蝎子的尾巴还毒）——莫得安其性命之情者，而犹自以为圣人，不可耻乎？其无耻也！子贡蹴蹴然立不安。"}]}),n[37]||(n[37]=a("h2",{id:"十、六经陈迹·孔子得道",tabindex:"-1"},[t("十、六经陈迹·孔子得道 "),a("a",{class:"header-anchor",href:"#十、六经陈迹·孔子得道","aria-label":'Permalink to "十、六经陈迹·孔子得道"'},"​")],-1)),n[38]||(n[38]=a("h3",{id:"原文-9",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-9","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:G,glossary:C,"default-mode":"classic","aria-label":"天运·六经陈迹 原文"}),n[39]||(n[39]=a("h3",{id:"生僻字词-9",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"陈迹",pinyin:["chén","jì"],meaning:"先王的足迹。六经是先王的陈迹——迹，履之所出，而迹岂履哉。"},{term:"与化为人",pinyin:["yǔ","huà","wéi","rén"],meaning:"与自然变化融为一体。不与化为人，安能化人：融入变化，方能感化别人。孔子得道的核心。"},{term:"乌鹊孺",pinyin:["wū","què","rú"],meaning:"乌鹊孵育。乌鹊孺，鱼傅沫：万物自然化育的例子。"},{term:"傅沫",pinyin:["fù","mò"],meaning:"鱼儿吐沫而化。乌鹊孺，鱼傅沫：万物不待外力而自然化育。"}]}),n[40]||(n[40]=a("h3",{id:"核心句引读-9",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"迹非履——六经，是先王的足迹，不是留下足迹的脚",subtitle:"苟得于道，无自而不可；失焉者，无自而可。",lines:[{text:"夫六经，先王之陈迹也，岂其所以迹哉！今子之所言，犹迹也。夫迹，履之所出，而迹岂履哉！",tone:"迹非履",guide:"孔子谓老聃：丘治六经，自以为久矣——以奸者七十二君（进说了七十二位君主），一君无所钩用（没有一个君主采纳）——甚矣！夫人之难说也？道之难明邪？老子曰：幸矣，子之不遇治世之君！——幸运啊，你没有遇到治世的君主！夫六经，先王之陈迹也（六经，是先王留下的足迹），岂其所以迹哉（难道是留下足迹的脚吗）！今子之所言，犹迹也（你所说的，还是足迹）——夫迹，履之所出，而迹岂履哉（足迹，是脚走出来的——但足迹，不是脚）！这，与《天道》「古人之糟粕」完全呼应：六经，是陈迹——是「语」的层面——「意之所随」（道），无法通过六经传递。"},{text:"性不可易，命不可变，时不可止，道不可壅。苟得于道，无自而不可；失焉者，无自而可。",tone:"四不变",guide:"夫白鶂之相视，眸子不运而风化（白鶂相视，眼珠不动，就能感应化育）；虫，雄鸣于上风，雌应于下风而风化（雄虫在上风鸣叫，雌虫在下风响应，感应化育）——类自为雌雄，故风化（同类自然分为雌雄，所以能感应化育）。性不可易（本性不可改变），命不可变（天命不可改变），时不可止（时机不可阻止），道不可壅（道不可堵塞）——苟得于道，无自而不可（得道，则无所不可）；失焉者，无自而可（失道，则无所可）。这四者（性·命·时·道），是不变的——本，永远不变——末（礼义法度），应时而变。"},{text:"丘得之矣。乌鹊孺，鱼傅沫，细要者化，有弟而兄啼。久矣，夫丘不与化为人！不与化为人，安能化人。",tone:"与化为人",guide:"孔子不出三月，复见——丘得之矣！乌鹊孺（乌鹊孵育），鱼傅沫（鱼儿吐沫而化），细要者化（细腰蜂感化而生），有弟而兄啼（弟弟出生，哥哥啼哭）——久矣，夫丘不与化为人（很久了，我没有与变化融为一体）！不与化为人，安能化人（不与变化融为一体，怎么能感化别人）！这，是《天运》对「教化」最深刻的定义：真正的教化，不是教——而是：你，成为变化本身——你，自然流出——别人，自然被感化。老子曰：可，丘得之矣！（可以，丘得到了！）——《天运》全篇的收束——最简洁的认可——孔子，最终，得到了。"}]}),n[41]||(n[41]=l("",38))])}}});export{I as __pageData,B as default};
